INSERT INTO feature VALUES('rule-symmetry','rules','A rule that swaps two arguments','rule-equations','implemented','notable',NULL,'A rule that swaps the two arguments of one operation, `f x y <=> f y x`, is a symmetry: it states that the operation is commutative. No reader rewrites by it, so the path order passes it with no orientation, and the kernel passes it at its admission of the rule table and of the theory value. A model of the theory owes the law as a member, and a case on the terms owes its respect, as for each rule. Each rule of the operation fires in the two orders of its arguments: the match of a left side tries each order at each node under a symmetry, so `meet x none` reads as `none` under the rule `meet none x <=> none`, and the kernel replays the rewriting by the same match. Two terms that differ by the order of two arguments convert: the conversion pairs the two fields of two constructors under a symmetry in the written order or crossed, the checker records the crossed pairing as a decision of the trace, and the kernel replays that decision only where its own rule table holds the symmetry. The rules converge on classes of terms under the symmetries: each critical pair is read in each order of its left sides, and two closed terms are apart where each pairing of the fields finds two distinct constructors, which the kernel decides again. A refutation of a conversion at two constructors under a symmetry is not authoritative.','theory-levitation kernel-term kernel-conversion-trace kernel-core core-nbe','corpus/model/desc/rule-symmetry.gandr corpus/pathological/desc/rule-symmetry.gandr corpus/model/desc/rule-symmetry-matched.gandr corpus/pathological/desc/rule-symmetry-matched.gandr corpus/model/desc/rule-symmetry-compared.gandr corpus/pathological/desc/rule-symmetry-compared.gandr corpus/model/desc/rule-symmetry-apart.gandr corpus/pathological/desc/rule-symmetry-apart.gandr','corpus/ledger/features/rule-symmetry.gandr',NULL);
